          size="small"
          label="New campaign"
          icon="pi pi-plus"
          onClick={() => router.push("/campaigns/new")}
        />
      </div>

      <AppDataTable
        data={rows}
        total={data?.total ?? 0}
        columns={columns}
        dataKey="id"
        loading={isLoading}
        searchPlaceholder="Search campaigns"
        filters={filters}
        actions={actions}
        onSearch={setSearch}
        onSort={setSorts}
        onFilter={setFilterValues}
        onPage={(offset, limit) => setPage({ offset: offset * limit, limit })}
      />
    </div>
  );
}

