    vi.mocked(repository.getSchedule).mockResolvedValue(null);

    await new GetScheduleQuery(repository).execute({
      id: "schedule-1",
      organizationId: "org-1",
    });
    expect(repository.getSchedule).toHaveBeenCalledWith("schedule-1", "org-1");
  });
});

