  3	import { useState } from "react";
  4	import type { DataTableSort } from "@/src/components/molecules/data-table";
  5	
  6	interface UseDataTableOptions {
  7	  defaultRows?: number;
  8	}
  9	
 10	export function useDataTable(options?: UseDataTableOptions) {
 11	  const [search, setSearch] = useState("");
 12	  const [sorts, setSorts] = useState<DataTableSort[]>([]);
 13	  const [filterValues, setFilterValues] = useState<Record<string, unknown>>({});
 14	  const [page, setPage] = useState({
 15	    offset: 0,
 16	    limit: options?.defaultRows ?? 10,
 17	  });
 18	
 19	  function buildQueryInput<T extends string>(sortFields: T[]) {
 20	    const normalizedFilters = Object.entries(filterValues).reduce<
 21	      Record<string, string>
 22	    >((acc, [key, value]) => {
 23	      if (typeof value === "string" && value) {
 24	        acc[key] = value;
 25	      }
 26	
 27	      return acc;
 28	    }, {});
 29	
 30	    const sort =
 31	      sorts.length > 0
 32	        ? sorts.reduce<Array<{ field: T; order: DataTableSort["order"] }>>(
 33	            (acc, currentSort) => {
 34	              if (sortFields.includes(currentSort.field as T)) {
 35	                acc.push({
 36	                  field: currentSort.field as T,
 37	                  order: currentSort.order,
 38	                });
 39	              }
 40	
 41	              return acc;
 42	            },
 43	            [],
 44	          )
 45	        : undefined;
 46	
 47	    return {
 48	      search: search || undefined,
 49	      limit: page.limit,
 50	      offset: page.offset,
 51	      sort: sort && sort.length > 0 ? sort : undefined,
 52	      filters:
 53	        Object.keys(normalizedFilters).length > 0
 54	          ? normalizedFilters
 55	          : undefined,
 56	    };
 57	  }
 58	
 59	  return {
 60	    search,
 61	    setSearch,
 62	    sorts,
 63	    setSorts,
 64	    filterValues,
 65	    setFilterValues,
 66	    page,
 67	    setPage,
 68	    buildQueryInput,
 69	  };
 70	}

