 47	export function useTableState(options: UseTableStateOptions = {}) {
 48	  const { defaultRows = 10, onSearch, onSort, onFilter, onPage } = options;
 49	
 50	  const [state, dispatch] = useReducer(tableReducer, {
 51	    first: 0,
 52	    rows: defaultRows,
 53	    search: "",
 54	    sorts: [],
 55	    filterValues: {},
 56	  });
 57	
 58	  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 59	
 60	  const setSearch = useCallback(
 61	    (value: string) => {
 62	      dispatch({ type: "SET_SEARCH", search: value });
 63	      if (searchTimeoutRef.current) {
 64	        clearTimeout(searchTimeoutRef.current);
 65	      }
 66	      searchTimeoutRef.current = setTimeout(() => {
 67	        onSearch?.(value);
