 79	        field: meta.field as string,
 80	        order: meta.order === 1 ? ("asc" as const) : ("desc" as const),
 81	      }));
 82	      dispatch({ type: "SET_SORTS", sorts: newSorts });
 83	      onSort(newSorts);
 84	    },
 85	    [onSort],
 86	  );
 87	
