 89	    (e: { first: number; rows: number }) => {
 90	      dispatch({ type: "SET_PAGE", first: e.first, rows: e.rows });
 91	      onPage?.(e.first / e.rows, e.rows);
 92	    },
 93	    [onPage],
 94	  );
 95	
 96	  const setFilter = useCallback(
 97	    (field: string, value: unknown) => {
 98	      const newFilters = { ...state.filterValues, [field]: value };
 99	      dispatch({ type: "SET_FILTERS", filterValues: newFilters });
100	      onFilter?.(newFilters);
101	      dispatch({ type: "RESET_PAGE" });
102	      onPage?.(0, state.rows);
103	    },
104	    [state.filterValues, onFilter, onPage, state.rows],
105	  );
106	
107	  const multiSortMeta: DataTableSortMeta[] = state.sorts.map((s) => ({
108	    field: s.field,
109	    order: s.order === "asc" ? 1 : -1,
110	  }));
111	
